// Before: every new shipping method edits this function.
function shippingCost(method, subtotal) {
  if (method === "standard") return subtotal >= 50 ? 0 : 4.99;
  else if (method === "express") return 12.5;
  else if (method === "pickup") return 0;
  throw new Error("unknown method");
}

// After: one table, one lookup.
const shippingStrategies = {
  standard: (subtotal) => (subtotal >= 50 ? 0 : 4.99),
  express: () => 12.5,
  pickup: () => 0,
};

function shippingCostFor(method, subtotal) {
  const strategy = shippingStrategies[method];
  if (!strategy) throw new Error(`unknown shipping method: ${method}`);
  return strategy(subtotal);
}

function createCheckout({ shipping, discounts, now = () => new Date() }) {
  return function checkout(order) {
    const subtotal = order.items.reduce((sum, i) => sum + i.price * i.qty, 0);
    const discount = order.coupon ? discounts[order.coupon](subtotal) : 0;
    return {
      subtotal,
      discount,
      shipping: shipping[order.shipping](subtotal - discount),
      placedAt: now().toISOString(),
    };
  };
}

// production
const checkout = createCheckout({ shipping: shippingStrategies, discounts: realDiscounts });
// test: deterministic clock, one simple discount
const testCheckout = createCheckout({
  shipping: { flat: () => 5 },
  discounts: { HALF: (s) => s / 2 },
  now: () => new Date("2026-01-01T00:00:00Z"),
});
